package io.floci.aws.services.configservice;

import com.fasterxml.jackson.databind.JsonNode;
import io.floci.aws.core.common.AwsException;
import io.floci.aws.core.common.RequestConstraintCheck;

import java.util.List;
import java.util.Set;

/**
 * Checks AWS Config requests against the constraints generated by {@code tools/aws/regen_config_shapes.py}.
 * A violation is a {@code ValidationException}, which the model documents for missing required fields and
 * input that fails validation. A {@code Limit} out of range answers {@code InvalidLimitException} instead
 * where the operation models it.
 */
final class ConfigRequestShapes {

    private static final Set<String> MODELED_LIMITS = Set.of(
            "DescribeAggregationAuthorizations.Limit", "DescribeConformancePacks.Limit",
            "DescribeConformancePackStatus.Limit", "ListTagsForResource.Limit");
    private static final RequestConstraintCheck.Messages VALIDATION =
            RequestConstraintCheck.standardMessages("ValidationException");
    private static final RequestConstraintCheck.Messages INVALID_LIMIT =
            RequestConstraintCheck.standardMessages("InvalidLimitException");

    private static final RequestConstraintCheck CHECK = RequestConstraintCheck.load(
            "aws/config-request-shapes.json", "AWS Config request shapes",
            new RequestConstraintCheck.Messages() {
                @Override
                public AwsException type(String path, String type) {
                    return VALIDATION.type(path, type);
                }

                @Override
                public AwsException bounds(String path, String type, Long min, Long max, Number size) {
                    return (MODELED_LIMITS.contains(path) ? INVALID_LIMIT : VALIDATION).bounds(path, type, min, max, size);
                }

                @Override
                public AwsException pattern(String path, String pattern) {
                    return VALIDATION.pattern(path, pattern);
                }

                @Override
                public AwsException enumValue(String path, List<String> values) {
                    return VALIDATION.enumValue(path, values);
                }

                @Override
                public AwsException required(String path) {
                    return VALIDATION.required(path);
                }
            });

    private ConfigRequestShapes() {
    }

    static void check(String operation, JsonNode request) {
        if (CHECK.hasOperation(operation)) {
            CHECK.check(operation, request);
        }
    }
}
